{
  "technical_and_design_decisions": [
    "Treat U1 and U2 as Java and Python client SDKs for interacting with Fabric through the existing public peer, orderer, certificate authority, and event APIs; the repeated NodeJS wording is treated as a specification typo.",
    "Preserve backward compatibility for existing Fabric APIs and wire protocols wherever practical, adding new interfaces rather than changing existing behavior.",
    "Implement pre-built user chaincode as deployable, platform-specific artifacts or images that can be launched by peers without requiring peer-side source code or compilation.",
    "Use a defined build-target matrix for pre-built chaincode and document unsupported operating-system and architecture combinations.",
    "For VSCC diagnostics, generate structured policy-evaluation details containing the policy expression, resolved signer identities, satisfied policy branches, and missing identities or organizations.",
    "Expose VSCC failure details through peer logs and transaction-validation or event-failure metadata while retaining the existing error status and compatibility fields.",
    "Implement certificate fingerprint validation using organization-controlled, signed fingerprint lists loaded as channel configuration, so validation is deterministic at commit time and does not depend on an external endpoint during endorsement.",
    "Represent fingerprint-list signing keys, list versions, validity periods, and rollover information in channel configuration, with explicit rejection of unsigned, expired, or incorrectly chained lists.",
    "Provide platform-specific release artifacts through the existing project build and CI mechanisms, with checksums and reproducible packaging where supported.",
    "Create a canonical config_defaults directory containing complete example/default YAML values for peer, orderer, and channel configuration, and link it from relevant documentation and BYFN instructions.",
    "Include unit tests, integration tests, release verification, and documentation as part of each feature's implementation effort."
  ],
  "assumptions": [
    "The increment includes implementation of all eight user stories, including production-quality tests and documentation.",
    "The developer has access to the existing Fabric source tree, build infrastructure, test environments, and standard development tools.",
    "One workday represents one developer workday; estimates measure effort and do not imply calendar duration or parallel execution.",
    "Existing Fabric SDK patterns, protobuf definitions, cryptographic libraries, policy evaluators, chaincode launch mechanisms, and release pipelines can be extended rather than replaced.",
    "The Java and Python SDKs provide a practical subset covering network connection, identity handling, transaction proposal/submission, query, and event consumption; complete parity with every internal Fabric capability is not assumed.",
    "The pre-built chaincode feature supports the existing chaincode programming models and a finite set of officially supported operating-system and CPU targets, rather than every possible environment.",
    "U3 does not include a new chaincode language, a new container runtime, or a new peer security model.",
    "For U4, peer and organization names can be resolved from available MSP and channel metadata; opaque identities are retained when a human-readable name cannot be resolved.",
    "For U6, channel configuration can be extended without redesigning Fabric CA issuance or revocation. The signed fingerprint-list approach is selected instead of externally hosted, endorsement-time lists.",
    "U6 includes a documented migration path for existing channels that do not configure fingerprint pinning; such channels continue using ordinary trust-root validation.",
    "U5 covers the tools currently maintained in the repository, including configtxgen, fabric-chaintool, Fabric CA client, and other release-managed command-line tools; it does not include third-party binaries.",
    "U7 uses and documents the existing test-network or equivalent repository test scripts rather than creating a separate orchestration platform.",
    "U8 documents the effective defaults for supported configuration variables and identifies values that are generated dynamically or supplied by environment variables.",
    "Code review, security review, and release approval are performed by the same developer as preparation activities; external organizational approval time is excluded."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment analysis and architecture planning",
      "activity_description": "Analyze the eight user stories, inspect existing Fabric interfaces and build layouts, define feature boundaries, compatibility constraints, data flows, test strategy, and implementation sequencing.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A2",
      "activity_name": "Java SDK core implementation",
      "activity_description": "Implement the Java SDK client abstractions, connection and configuration handling, enrollment and identity use, proposal/query/transaction submission flows, and basic event support using existing Fabric protocols.",
      "most_likely_effort": 22
    },
    {
      "activity_id": "A3",
      "activity_name": "Java SDK tests and documentation",
      "activity_description": "Create Java SDK unit and integration tests, example applications, API documentation, error handling coverage, and packaging/build configuration.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A4",
      "activity_name": "Python SDK core implementation",
      "activity_description": "Implement the Python SDK equivalent client functionality, including connection profiles, identities, proposals, queries, transaction submission, and event consumption.",
      "most_likely_effort": 22
    },
    {
      "activity_id": "A5",
      "activity_name": "Python SDK tests and documentation",
      "activity_description": "Create Python SDK unit and integration tests, usage examples, API documentation, packaging metadata, and compatibility/error-path coverage.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A6",
      "activity_name": "Pre-built chaincode deployment design",
      "activity_description": "Define the artifact or image format, peer deployment flow, metadata, trust and validation rules, supported build targets, source-code isolation behavior, and compatibility with existing chaincode lifecycle operations.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A7",
      "activity_name": "Pre-built chaincode peer and packaging implementation",
      "activity_description": "Modify peer chaincode installation, validation, launch, and lifecycle handling so peers can use pre-built user chaincode without compiling or retaining source code; implement artifact packaging and metadata handling.",
      "most_likely_effort": 25
    },
    {
      "activity_id": "A8",
      "activity_name": "Pre-built target builds and release integration",
      "activity_description": "Add build definitions for the supported operating-system and architecture combinations, integrate artifact creation into CI or release scripts, and provide installation and deployment commands.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A9",
      "activity_name": "Pre-built chaincode testing and documentation",
      "activity_description": "Test successful deployment, startup, upgrades, failure handling, source absence, multiple peer environments, and compatibility with representative chaincode; document the workflow and supported targets.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A10",
      "activity_name": "VSCC policy-failure diagnostic implementation",
      "activity_description": "Extend VSCC policy evaluation and validation error handling to capture the evaluated policy, signer identities, organization memberships, satisfied branches, and missing signer or organization requirements.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A11",
      "activity_name": "VSCC logs and failure-event propagation",
      "activity_description": "Add human-readable INFO-level diagnostic logging and propagate structured failure details through transaction validation results and event-notification paths while preserving existing error behavior.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A12",
      "activity_name": "VSCC diagnostic test coverage",
      "activity_description": "Add policy tests for AND, OR, threshold, nested, satisfied, and missing branches; verify signer naming, organization resolution, log output, event payloads, and backward compatibility.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A13",
      "activity_name": "Platform binary build and packaging automation",
      "activity_description": "Inventory required tools, extend build and release automation for supported platforms, produce archives and checksums, and package configtxgen, fabric-chaintool, Fabric CA client, and other maintained tools.",
      "most_likely_effort": 22
    },
    {
      "activity_id": "A14",
      "activity_name": "Binary verification and distribution documentation",
      "activity_description": "Verify executable behavior on target platforms, test archive installation and version reporting, document download and verification procedures, and update release instructions.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A15",
      "activity_name": "Certificate fingerprint validation architecture",
      "activity_description": "Define the channel configuration model, cryptographic formats, signing and verification rules, identity-to-organization mapping, failure semantics, migration behavior, and security boundaries for pinned certificate fingerprints.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A16",
      "activity_name": "Fingerprint-list configuration and data model",
      "activity_description": "Implement channel configuration structures for organization fingerprint lists, trusted roots, signing keys, list versions, validity periods, and key rollover metadata, including serialization and validation.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "A17",
      "activity_name": "Certificate and fingerprint validation integration",
      "activity_description": "Integrate ordinary certificate-chain validation with optional organization-controlled fingerprint checks at the appropriate endorsement or validation boundary, including configuration lookup and clear rejection errors.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A18",
      "activity_name": "Fingerprint security, rollover, and compatibility handling",
      "activity_description": "Implement signed-list verification, key rollover, expiration and replay protections, malformed-input handling, disabled-feature behavior, and compatibility for channels without fingerprint configuration.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A19",
      "activity_name": "Certificate fingerprint integration and security tests",
      "activity_description": "Test valid and invalid chains, matching and nonmatching fingerprints, unauthorized list changes, signing-key rollover, expiry, multiple organizations, malformed configuration, and deterministic validation behavior.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A20",
      "activity_name": "Certificate fingerprint documentation",
      "activity_description": "Document channel configuration, fingerprint generation and signing, key management, rollover, operational procedures, migration, error messages, and security limitations.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A21",
      "activity_name": "Quick-start Fabric test network improvements",
      "activity_description": "Improve or add scripts for rapidly starting a representative Fabric network, deploying sample or user chaincode, exercising existing tools, and integrating custom chaincode framework tests.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "A22",
      "activity_name": "Configuration defaults inventory and canonical files",
      "activity_description": "Inspect source code and configuration consumers, enumerate effective peer, gossip, ledger, endorser, orderer, Kafka, and channel defaults, and create complete files under a config_defaults directory.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A23",
      "activity_name": "Testing and documentation for test network and defaults",
      "activity_description": "Validate quick-start instructions and default configuration files, identify generated or environment-dependent values, update testing documentation, readme files, documentation links, and BYFN instructions.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A24",
      "activity_name": "Cross-feature integration, regression, and final packaging",
      "activity_description": "Run the combined regression suite, resolve cross-feature integration issues, verify SDK and binary packaging, perform final cleanup, and prepare the complete increment for delivery.",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 353
  }
}

